ALTER POLICY "visible reports" ON public.campus_reports USING(user_id=auth.uid() OR public.campus_capability('admin'));
ALTER POLICY "own reports create" ON public.campus_reports WITH CHECK(user_id=auth.uid() AND status='Open' AND department='' AND (kind='Feedback' OR rating IS NULL) AND (photo_path IS NULL OR split_part(photo_path,'/',1)=auth.uid()::text));
CREATE FUNCTION public.lost_found_feed() RETURNS TABLE(id uuid,kind text,title text,description text,category text,photo_path text,status text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id,kind,title,description,category,photo_path,status,created_at FROM public.campus_reports WHERE kind IN ('Lost','Found') ORDER BY created_at DESC $$; REVOKE ALL ON FUNCTION public.lost_found_feed() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.lost_found_feed() TO authenticated;
CREATE FUNCTION public.public_item_photo(path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.campus_reports WHERE photo_path=path AND kind IN ('Lost','Found')) $$; REVOKE ALL ON FUNCTION public.public_item_photo(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_item_photo(text) TO authenticated;
ALTER POLICY "read report photo" ON storage.objects USING(bucket_id='campus-reports' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.campus_capability('admin') OR public.public_item_photo(name)));
CREATE FUNCTION public.claimable_item(item uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.campus_reports WHERE id=item AND kind='Found' AND status<>'Resolved') $$; REVOKE ALL ON FUNCTION public.claimable_item(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.claimable_item(uuid) TO authenticated;
ALTER POLICY "claim found item" ON public.item_claims WITH CHECK(user_id=auth.uid() AND status='Pending' AND public.claimable_item(report_id));
CREATE POLICY "approved schedule management" ON public.campus_schedule FOR ALL TO authenticated USING(public.campus_capability('admin') OR public.campus_capability('faculty')) WITH CHECK(public.campus_capability('admin') OR public.campus_capability('faculty'));
CREATE FUNCTION public.guard_claim_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.id,NEW.report_id,NEW.user_id,NEW.evidence,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.report_id,OLD.user_id,OLD.evidence,OLD.created_at) THEN RAISE EXCEPTION 'Only claim decision may change'; END IF; RETURN NEW; END $$; CREATE TRIGGER guard_claim_identity BEFORE UPDATE ON public.item_claims FOR EACH ROW EXECUTE FUNCTION public.guard_claim_identity();